<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Database; use App\Core\HttpException; use App\Core\Request; use App\Core\Response; use App\Core\ValidationException; use App\Core\Validator; use App\Models\Account; use App\Models\Category; use App\Models\Goal; use App\Models\Transaction;
/** Gerencia metas e suas contribuições, incluindo retirada e devolução de saldo. */
final class GoalController extends Controller
{
    public function index(Request $r): never { Response::json(Goal::allForUser($this->userId($r))); }
    public function store(Request $r): never { Response::json(Goal::create($this->userId($r),$this->validated($r)),201); }
    public function show(Request $r): never { $id=$this->id($r,'goal');$g=Goal::findForUser($id,$this->userId($r))??$this->notFound();$g['transactions']=Goal::contributions($id,$this->userId($r));Response::json($g); }
    public function update(Request $r): never { $id=$this->id($r,'goal');$g=Goal::findForUser($id,$this->userId($r))??$this->notFound();$d=$this->validated($r);if((float)$d['target_amount']<(float)$g['current_amount']){throw new ValidationException(['target_amount'=>['O objetivo não pode ser menor que o valor já contribuído.']]);}Response::json(Goal::update($id,$this->userId($r),$d)); }
    /** Excluir uma meta também estorna todas as contribuições. */
    public function destroy(Request $r): never { $id=$this->id($r,'goal');Database::transaction(function()use($r,$id){$uid=$this->userId($r);Goal::findForUser($id,$uid)??$this->notFound();foreach(Goal::contributions($id,$uid) as $t){$a=Account::findForUser((int)$t['account_id'],$uid,true)??$this->notFound();Account::updateBalance((int)$a['id'],(float)$a['balance']+(float)$t['contributed_amount']);Transaction::delete((int)$t['id']);}Goal::delete($id,$uid);});Response::json(null,204); }
    /** Reserva saldo e registra uma despesa auditável para a contribuição. */
    public function contribute(Request $r): never { $id=$this->id($r,'goal');$d=Validator::validate($r->all(),['account_id'=>['required','integer'],'amount'=>['required','numeric','gt:0']]);$result=Database::transaction(function()use($r,$id,$d){$uid=$this->userId($r);$g=Goal::findForUser($id,$uid)??$this->notFound();$a=Account::findForUser((int)$d['account_id'],$uid,true)??$this->notFound();if($a['status']!=='active'){throw new HttpException(404,'Conta ativa não encontrada.');}if((float)$d['amount']>(float)$a['balance']){throw new ValidationException(['amount'=>['Saldo insuficiente para realizar esta contribuição.']]);}if((float)$g['current_amount']+(float)$d['amount']>(float)$g['target_amount']){throw new ValidationException(['amount'=>['A contribuição não pode ultrapassar o valor restante da meta.']]);}$c=Category::goalContribution($uid);Account::updateBalance((int)$a['id'],(float)$a['balance']-(float)$d['amount']);$t=Transaction::create(['user_id'=>$uid,'account_id'=>$a['id'],'category_id'=>$c['id'],'description'=>'Contribuição: '.$g['title'],'amount'=>$d['amount'],'type'=>'expense','transaction_date'=>date('Y-m-d')]);Goal::attachContribution($id,(int)$t['id'],(float)$d['amount']);return ['goal'=>Goal::findForUser($id,$uid),'transaction'=>$t];});Response::json($result,201); }
    public function removeContribution(Request $r): never { $goalId=$this->id($r,'goal');$transactionId=$this->id($r,'transaction');Database::transaction(function()use($r,$goalId,$transactionId){$uid=$this->userId($r);Goal::findForUser($goalId,$uid)??$this->notFound();$t=Transaction::findForUser($transactionId,$uid)??$this->notFound();$contribution=Goal::contribution($goalId,$transactionId)??$this->notFound();$a=Account::findForUser((int)$t['account_id'],$uid,true)??$this->notFound();Account::updateBalance((int)$a['id'],(float)$a['balance']+(float)$contribution['contributed_amount']);Goal::detachContribution($goalId,$transactionId);Transaction::delete($transactionId);});Response::json(null,204); }
    private function validated(Request $r): array { $d=Validator::validate($r->all(),['title'=>['required','string','min:3','max:100'],'target_amount'=>['required','numeric','gt:0'],'deadline'=>['nullable','date']]);$d['deadline']=$d['deadline']??null;return $d; }
}
